  locals { n d } {
    d d prim * n prim <
    [ n d prim mod 0 prim = [ 0 ] [ d 1 prim + n checkdivisor ] if ]
    [ 1 ]
    if
  };

: isprime
  (forall ρ; ρ n:Int^many -- ρ prime:Bool^many)
  locals { n } {
    n 2 prim <
    [ 0 ]
    [ n 2 prim = [ 1 ] [ n 2 checkdivisor ] if ]
    if
  };

: primesaux
